-- Every query is scoped by project_id. Soft-deleted endpoints (deleted_at IS
-- NOT NULL) are invisible to the API. secret_ciphertext is only returned by
-- GetEndpointSecret, never by listing/reading queries.

-- Serializes endpoint creation per project so the endpoint limit holds under
-- concurrency.
-- name: LockProject :one
SELECT id FROM projects
WHERE id = @project_id
FOR UPDATE;

-- name: CountActiveEndpoints :one
SELECT count(*) FROM endpoints
WHERE project_id = @project_id
  AND deleted_at IS NULL;

-- The id is generated by the caller so the secret's ciphertext can be bound
-- to it (authenticated associated data) before insert.
-- name: CreateEndpoint :one
INSERT INTO endpoints (id, project_id, url, description, event_types, secret_ciphertext, enabled)
VALUES (@id, @project_id, @url, @description, @event_types, @secret_ciphertext, @enabled)
RETURNING id, project_id, url, description, event_types, enabled, created_at, updated_at;

-- name: GetEndpoint :one
SELECT id, project_id, url, description, event_types, enabled, created_at, updated_at
FROM endpoints
WHERE project_id = @project_id
  AND id = @id
  AND deleted_at IS NULL;

-- name: GetEndpointSecret :one
SELECT secret_ciphertext
FROM endpoints
WHERE project_id = @project_id
  AND id = @id
  AND deleted_at IS NULL;

-- Newest first; keyset pagination on (created_at, id).
-- name: ListEndpoints :many
SELECT id, project_id, url, description, event_types, enabled, created_at, updated_at
FROM endpoints
WHERE project_id = @project_id
  AND deleted_at IS NULL
  AND (sqlc.narg(cursor_created_at)::timestamptz IS NULL
       OR (created_at, id) < (sqlc.narg(cursor_created_at)::timestamptz, sqlc.narg(cursor_id)::uuid))
ORDER BY created_at DESC, id DESC
LIMIT @row_limit;

-- NULL arguments leave the column unchanged.
-- name: UpdateEndpoint :one
UPDATE endpoints
SET url         = coalesce(sqlc.narg(url), url),
    description = coalesce(sqlc.narg(description), description),
    event_types = coalesce(sqlc.narg(event_types)::text[], event_types),
    enabled     = coalesce(sqlc.narg(enabled), enabled)
WHERE project_id = @project_id
  AND id = @id
  AND deleted_at IS NULL
RETURNING id, project_id, url, description, event_types, enabled, created_at, updated_at;

-- name: SoftDeleteEndpoint :execrows
UPDATE endpoints
SET deleted_at = now(),
    enabled    = false
WHERE project_id = @project_id
  AND id = @id
  AND deleted_at IS NULL;

-- Deliveries not yet handed to a worker are cancelled when their endpoint is
-- disabled or deleted. queued/in_flight rows are left to the worker (Phase 3),
-- which must re-check the endpoint before sending.
-- name: CancelPendingDeliveriesForEndpoint :execrows
UPDATE deliveries
SET status       = 'cancelled',
    completed_at = now()
WHERE project_id = @project_id
  AND endpoint_id = @endpoint_id
  AND status IN ('pending', 'scheduled');
